<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, session } from '../../shared/api'
import { catalog, showError } from '../../shared/state'
import type { Report } from '../../shared/types'
import { addDays, feeNames, money, shortDate, statusNames } from '../../shared/format'
import Icon from '../../shared/Icon.vue'
import Badge from '../../shared/Badge.vue'
const emit = defineEmits<{openOrder: [id: string]}>()
const basis = ref('actual'), from = ref(addDays(session.today, -14)), to = ref(addDays(session.today, 7)), hotelId = ref(session.user?.role === 'HOTEL' ? session.user.hotelId : ''), report = ref<Report>(), busy = ref(false), detailTab = ref('daily')
const params = computed(() => new URLSearchParams({basis: basis.value, from: from.value, to: to.value, hotelId: hotelId.value}).toString())
const max = computed(() => Math.max(1, ...(report.value?.daily.map(d => Math.max(d.planned, d.actual)) || [])))
const sparseDaily = computed(() => report.value?.daily.filter(d => d.planned || d.actual) || [])
async function load() { busy.value = true; try { report.value = await api<Report>('/reports/stays?' + params.value) } catch (e) { showError(e) } finally { busy.value = false } }
onMounted(load)
function download() { if (!report.value) return; const q = new URLSearchParams({basis: report.value.basis, from: report.value.from, to: report.value.to, hotelId: hotelId.value}); window.location.href = '/api/reports/stays.csv?' + q }
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">HOSPITALITY INSIGHTS</span><h1>接待住宿统计</h1><p>按明确的日期口径汇总人次、去重人数、间夜及分类费用，并可追溯明细。</p></div><button class="button secondary" :disabled="!report" @click="download"><Icon name="download" :size="17"/>导出当前范围</button></div>
  <section class="card"><form @submit.prevent="load"><div class="report-filters"><div><label>日期统计口径</label><div class="segmented"><button type="button" :class="{active: basis === 'created'}" @click="basis = 'created'">下单日期</button><button type="button" :class="{active: basis === 'planned'}" @click="basis = 'planned'">计划住宿日期</button><button type="button" :class="{active: basis === 'actual'}" @click="basis = 'actual'">实际住宿日期</button></div></div><div class="form-grid two"><label>开始日期<input v-model="from" type="date" required/></label><label>结束日期<input v-model="to" type="date" :min="from" required/></label></div><label>酒店范围<select v-model="hotelId" :disabled="session.user?.role === 'HOTEL'"><option value="">全部授权酒店</option><option v-for="h in (catalog?.reportHotels || catalog?.hotels)" :key="h.id" :value="h.id">{{ h.name }}{{ h.deletedAt ? '（已删除·历史）' : '' }}</option></select></label></div><div class="search-form-footer"><p class="muted">人次按订单累计，去重人数按来宾身份统计。切换条件后点击查询更新结果。</p><button class="button primary" :disabled="busy">{{ busy ? '正在统计…' : '查询统计' }}</button></div></form></section>
  <template v-if="report"><p class="report-scope">当前结果：{{ ({created:'下单日期',planned:'计划住宿日期',actual:'实际住宿日期'})[report.basis as 'created'|'planned'|'actual'] }}口径 · {{ shortDate(report.from) }} — {{ shortDate(report.to) }}</p><div class="metric-grid five"><div class="metric-card"><span>预订人次</span><strong>{{ report.visits }}</strong><small>当前口径相关订单的来宾人次</small></div><div class="metric-card"><span>去重人数</span><strong>{{ report.uniquePeople }}</strong><small>按来宾身份去重</small></div><div class="metric-card"><span>实际间夜</span><strong>{{ report.actualNights }}</strong><small>仅核实并已发生的住宿晚</small></div><div class="metric-card"><span>计划 / 未来间夜</span><strong>{{ report.plannedNights }} <em>/ {{ report.futureNights }}</em></strong><small>未来部分不计入实际</small></div><div class="metric-card accent"><span>实际住宿费用</span><strong class="money-metric">¥ {{ money(report.actualCost) }}</strong><small>按已住晚锁定价格核算</small></div></div><div class="report-columns"><section class="card"><div class="section-heading"><h2>逐晚间夜分布</h2><div class="chart-legend"><span><i></i>已住</span><span><i class="light"></i>计划</span></div></div><p class="muted small">住宿晚逐日归属；停业关闭原单的已住部分仍计入实际。</p><div v-if="!sparseDaily.length" class="empty-state"><h3>当前范围暂无间夜数据</h3></div><div v-else class="chart-scroll"><div class="bar-chart" :style="{minWidth: Math.max(380, sparseDaily.length * 64) + 'px'}" role="img" aria-label="计划与实际间夜对比，详细数据见下方逐日明细"><div v-for="d in sparseDaily" :key="d.date" class="chart-column"><div class="bar-pair"><div class="chart-bar actual-bar" :style="{height: Math.max(2, d.actual / max * 150) + 'px'}"><span v-if="d.actual">{{ d.actual }}</span></div><div class="chart-bar planned-bar" :style="{height: Math.max(2, d.planned / max * 150) + 'px'}"><span v-if="d.planned">{{ d.planned }}</span></div></div><small>{{ d.date.slice(5).replace('-', '/') }}</small></div></div></div></section><section class="card fee-summary"><h2>费用分类</h2><div class="detail-row"><span>计划住宿费用</span><strong>¥ {{ money(report.plannedCost) }}</strong></div><div class="detail-row"><span>实际住宿费用</span><strong class="purple">¥ {{ money(report.actualCost) }}</strong></div><div v-for="(value, key) in report.fees" :key="key" class="detail-row"><span>{{ feeNames[key] }}</span><strong>¥ {{ money(value) }}</strong></div><div class="detail-row"><span>待核对 / 有争议费用</span><strong>¥ {{ money(report.pendingFees) }}</strong></div><p class="muted small">{{ report.notes }}</p></section></div><section class="card gap-top"><div class="admin-tabs"><button :class="{active: detailTab === 'daily'}" @click="detailTab = 'daily'">逐日明细</button><button :class="{active: detailTab === 'orders'}" @click="detailTab = 'orders'">订单与状态分项</button><button :class="{active: detailTab === 'fees'}" @click="detailTab = 'fees'">独立费用明细</button></div><div v-if="detailTab === 'daily'" class="table-wrap"><table><thead><tr><th>住宿日期</th><th>计划间夜</th><th>实际间夜</th><th>计划费用</th><th>实住费用</th></tr></thead><tbody><tr v-for="d in sparseDaily" :key="d.date"><td>{{ shortDate(d.date) }}</td><td>{{ d.planned }}</td><td>{{ d.actual }}</td><td>¥ {{ money(d.plannedCost) }}</td><td>¥ {{ money(d.actualCost) }}</td></tr><tr v-if="!sparseDaily.length"><td colspan="5" class="muted">暂无明细。</td></tr></tbody></table></div><template v-if="detailTab === 'orders'"><div class="status-summary"><span v-for="(count, key) in report.statusCounts" :key="key">{{ statusNames[key] || key }}：<strong>{{ count }}</strong></span></div><div class="table-wrap"><table><thead><tr><th>订单</th><th>酒店</th><th>住宿区间</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="o in report.orders" :key="o.id"><td>{{ o.code }}</td><td>{{ o.hotelName }}</td><td>{{ shortDate(o.startDate) }} — {{ shortDate(o.endDate) }}</td><td><Badge :status="o.status"/></td><td><button class="text-button" @click="emit('openOrder',o.id)">查看来源订单</button></td></tr></tbody></table></div></template><div v-if="detailTab === 'fees'" class="table-wrap"><table><thead><tr><th>订单</th><th>类别</th><th>金额</th><th>核对状态</th><th>依据</th></tr></thead><tbody><tr v-for="f in report.feeDetails" :key="f.id"><td>{{ f.orderCode }}</td><td>{{ feeNames[f.category] }}</td><td>¥ {{ money(f.amount) }}</td><td><Badge :status="f.status"/></td><td>{{ f.note }}</td></tr><tr v-if="!report.feeDetails.length"><td colspan="5" class="muted">当前登记日期范围无独立费用记录。</td></tr></tbody></table></div></section></template>
</template>
